// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.llm.localimport android.app.ActivityManagerimport android.content.Contextimport com.roshan.persona.brain.llm.registry.LocalLlmModelimport com.roshan.persona.brain.llm.registry.LocalLlmModelCatalog/** * NOUS — App-Heap-Aware Quantization Selector. * * v2.1 Fix #5: Uses `getMemoryClass()` (App Heap limit) NOT total device RAM. * Android gives each app a heap limit (192-512MB normal, up to 1GB largeHeap). * If we detect 12GB total RAM but App Heap is 256MB → loading 7GB Q8 model * would OOM-kill the app (App Heap exceeded, not total RAM). * * Selection logic: *   - App Heap > 512MB → Q8_0 (near-lossless, best quality) *   - App Heap > 256MB → Q4_K_M (balanced, recommended) *   - App Heap < 256MB → Q2_K (survival, lower quality) * * @see <a href="docs/strategy/module-4-strategy-v2.1.md">§5 App-Heap-Aware Quantization</a> */object QuantizationSelector {    /**     * Get App Heap limit in MB (NOT total device RAM).     * Uses `ActivityManager.memoryClass` (normal heap).     * Returns 256 (conservative default) if ActivityManager unavailable.     */    fun getAppHeapMb(context: Context): Int {        val am = context.getSystemService(Context.ACTIVITY_SERVICE) as? ActivityManager            ?: return 256        return am.memoryClass    }    /**     * Get largeHeap limit in MB (if `android:largeHeap="true"` in manifest).     * Returns 512 (conservative default) if ActivityManager unavailable.     */    fun getLargeHeapMb(context: Context): Int {        val am = context.getSystemService(Context.ACTIVITY_SERVICE) as? ActivityManager            ?: return 512        return am.largeMemoryClass    }    /**     * Recommend best quantization based on APP HEAP (not total RAM).     */    fun recommendQuantization(appHeapMb: Int): String {        return when {            appHeapMb > 512 -> "Q8_0"            appHeapMb > 256 -> "Q4_K_M"            else -> "Q2_K"        }    }    /**     * Recommend best model size based on App Heap.     */    fun recommendModelSize(appHeapMb: Int): String {        return when {            appHeapMb > 512 -> "1.5B"            appHeapMb > 256 -> "0.5B"            else -> "0.5B"        }    }    /**     * Get recommended model for this device (App Heap based).     */    fun recommendModel(context: Context, catalog: LocalLlmModelCatalog): LocalLlmModel? {        val appHeapMb = getAppHeapMb(context)        val size = recommendModelSize(appHeapMb)        val quant = recommendQuantization(appHeapMb)        // Find matching model in catalog        return catalog.getAll().find { model ->            model.quantization == quant && model.architecture.contains(size, ignoreCase = true)        } ?: catalog.getDefault()    }    /**     * Estimate model file size based on parameter count and quantization.     */    fun estimateSize(modelSize: String, quant: String): Long {        val params = when (modelSize) {            "1.5B" -> 1_500_000_000L            "0.5B" -> 500_000_000L            else -> 500_000_000L        }        val bytesPerParam = when (quant) {            "Q8_0" -> 1.0f            "Q6_K" -> 0.75f            "Q4_K_M" -> 0.5f            "Q2_K" -> 0.3f            else -> 0.5f        }        return (params * bytesPerParam).toLong()    }}